function contarPrimos(n) {
  if (n < 3) return 0;
  const compuesto = new Uint8Array(n);
  let cuenta = 0;
  for (let p = 2; p < n; p++) {
    if (compuesto[p]) continue;
    cuenta++;
    for (let m = p * p; m < n; m += p) compuesto[m] = 1;
  }
  return cuenta;
}

solution.python:
def contarPrimos(n):
    if n < 3:
        return 0
    es_primo = bytearray([1]) * n
    es_primo[0] = es_primo[1] = 0
    p = 2
    while p * p < n:
        if es_primo[p]:
            es_primo[p * p::p] = bytearray(len(range(p * p, n, p)))
        p += 1
    return sum(es_primo)
